"""Build Social Luxe's dependency-free website: python3 build.py."""
from pathlib import Path
import html, json, shutil, re
ROOT = Path(__file__).resolve().parent
PUBLIC = ROOT / 'public'
PUBLIC.mkdir(exist_ok=True)
# Retire the old standalone archive and decorative scene from generated output.
shutil.rmtree(PUBLIC / 'work', ignore_errors=True)
(PUBLIC / 'material-scene.js').unlink(missing_ok=True)
shutil.copytree(ROOT / 'assets', PUBLIC / 'assets', dirs_exist_ok=True)
for name in ('styles.css', 'app.js', 'motion-gallery.js', 'hover-effects.js'):
    if (ROOT / name).exists(): shutil.copyfile(ROOT / name, PUBLIC / name)
PROJECTS = json.loads((ROOT / 'projects.json').read_text())

def arrow(cls=''):
    return f'<span class="arrow-icon {cls}" aria-hidden="true"><svg viewBox="4 4 16 16" fill="none"><path d="M7.5 16.5 16.5 7.5M7.5 7.5h9v9" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg></span>'
def unify_arrows(markup):
    markup = re.sub(r'<span(?: class="arrow")? aria-hidden="true">↗</span>', arrow(), markup)
    return markup.replace('↗', arrow())
def button(label, href, cls=''):
    return f'<a class="button {cls}" data-shine href="{href}">{label}{arrow()}</a>'
def wordmark():
    return 'Social Luxe<span class="brand-period">.</span>'
def concierge_mark(tag='h2'):
    return f'<{tag} class="luxe-mark">Luxe Concierge<span class="luxe-signature"><span class="script">by</span> <span class="brand">{wordmark()}</span></span></{tag}>'
def header(active=''):
    items = [('Marketing','/marketing/','marketing'),('Concierge','/concierge/','concierge'),('The house','/the-house/','house')]
    links = ''.join(f'<a href="{url}" class="nav-link"' + (' aria-current="page"' if active == key else '') + f'>{label}</a>' for label,url,key in items)
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="shell header-inner"><a class="brand" href="/" aria-label="Social Luxe home">{wordmark()}</a><nav class="desktop-nav" aria-label="Main navigation">{links}</nav>{button('Let’s talk','/enquire/','header-action')}<button class="menu-toggle" aria-label="Open menu" aria-controls="mobile-menu" aria-expanded="false"><span></span><span></span></button></div></header><div id="mobile-menu" class="mobile-menu" hidden><nav aria-label="Mobile navigation">{links}{button('Make an enquiry','/enquire/')}</nav><p>Bali, Indonesia. Working internationally.</p></div>'''
def footer():
    return f'''<footer class="site-footer"><div class="shell"><div class="footer-top"><div><a class="brand" href="/">{wordmark()}</a><p class="footer-description">Based in Bali.<br>Working internationally.</p></div><div class="footer-nav"><div class="footer-column"><span class="eyebrow">Explore</span><a href="/marketing/">Marketing</a><a href="/concierge/">Luxe Concierge</a><a href="/the-house/">The house</a></div><div class="footer-column"><span class="eyebrow">In conversation</span><a href="/enquire/">Make an enquiry ↗</a><a href="mailto:hello@socialluxe.com.au">hello@socialluxe.com.au</a><a href="https://www.instagram.com/social_luxe/" target="_blank" rel="noopener noreferrer">@social_luxe ↗</a><a href="https://www.instagram.com/luxeconciergebysl/" target="_blank" rel="noopener noreferrer">@luxeconciergebysl ↗</a></div></div></div><div class="footer-bottom"><span>© 2026 Social Luxe.</span><span>Bali · Indonesia · Worldwide enquiries</span><a href="/privacy/">Privacy &amp; enquiries</a></div></div></footer>'''
def contact_band():
    return f'''<section class="contact-band"><div class="shell"><p class="eyebrow reveal">Start a conversation</p><div class="contact-band-inner"><h2 class="reveal">What do you<br>have in <span class="script">mind?</span></h2><div class="contact-options reveal"><p>A brand brief. A private occasion.<br>Tell us what you’re planning.</p>{button('Discuss a campaign','/enquire/?service=marketing')}{button('Plan a private booking','/enquire/?service=concierge','button-outline')}</div></div></div></section>'''
def logo(p):
    return f'<img class="partner-logo" src="/assets/logos/{p["logo"]}" alt="{html.escape(p["partner"])}" loading="lazy">' if p.get('logo') else html.escape(p['partner'])
def card(p):
    return f'''<article class="project-card" id="{p['id']}" data-category="{p['category']}"><a class="project-cover" data-tilt href="/marketing/#{p['id']}" data-project="{p['id']}" aria-label="Explore {html.escape(p['title'])}"><span class="project-image"><img class="project-photo" src="/assets/projects/{p['image']}.jpg" alt="{html.escape(p['credit'])}" width="1080" height="1440" loading="lazy"><span class="project-type">{p['categoryLabel']}</span><span class="project-logo">{logo(p)}</span>{arrow('project-open')}</span></a><div class="project-caption"><h3>{p['title']}</h3><p>{p['place']} <span>{p['date']}</span></p></div></article>'''
def work_section(projects=PROJECTS, heading='Selected work.', full=False):
    filters = f'''<div class="work-filters" role="group" aria-label="Filter projects"><button class="active" data-filter="all" aria-pressed="true">All projects <span>{len(projects):02d}</span></button><button data-filter="partnerships" aria-pressed="false">Brand partnerships</button><button data-filter="events" aria-pressed="false">Events &amp; VIP</button><button data-filter="hosting" aria-pressed="false">Private hosting</button></div>'''
    controls = f'''<div class="gallery-controls"><p class="gallery-status" aria-live="polite">{len(projects)} projects</p><div><button class="gallery-prev" aria-label="Previous projects">←</button><button class="gallery-next" aria-label="Next projects">→</button></div></div>'''
    status = f'<p class="gallery-status sr-only" aria-live="polite">{len(projects)} projects</p>'
    return f'''<section id="work" class="work-section section" data-gallery><div class="shell"><div class="section-head reveal"><div><p class="eyebrow">People, brands &amp; places</p><h2 class="section-title">{heading}</h2></div><p>Creator collaborations, brand events<br>and private experiences in Bali.</p></div>{filters if full else ''}</div><div class="project-rail {'project-grid' if full else ''}" tabindex="0" role="region" aria-label="Selected collaborations">{''.join(card(p) for p in projects)}</div><div class="shell">{status if full else controls}<p class="source-note">From the Social Luxe and Luxe Concierge archives. Each project links to its original publication.</p></div></section>'''
VENUES = [
    {'partner':'Savaya','logo':'savaya.svg','url':'https://www.savaya.com/','project':'savaya'},
    {'partner':'Desa Kitsuné','logo':'desa-kitsune.png','url':'https://desakitsune.com/','image':'desa-kitsune.jpg','label':'Music, dining &amp; culture'},
    {'partner':'Zumana','logo':'zumana.svg','url':'https://zumanabali.com/','project':'zumana'},
    {'partner':'Giselle','logo':'giselle.svg','url':'https://gisellebali.com/','image':'giselle.jpg','label':'Dining &amp; evenings'},
    {'partner':'Bella','logo':'bella.png','url':'https://bellacanggu.com/','image':'bella.jpeg','label':'Dining &amp; nightlife'},
]
def brand_strip():
    marks = ''.join(f'<a href="/marketing/#{v.get("project", "venues")}" aria-label="Discover {v["partner"]}">{logo(v)}</a>' for v in VENUES)
    return f'''<section class="brand-strip shell" aria-label="Venues we work with"><p class="eyebrow">Around the island. In good company.</p><div class="brand-logos">{marks}</div></section>'''
def venue_section():
    cards = ''.join(f'''<a class="venue-card" data-tilt href="{v['url']}" target="_blank" rel="noopener noreferrer" aria-label="Visit {v['partner']} website"><span class="venue-image"><img src="/assets/venues/{v['image']}" alt="{v['partner']}, Bali" loading="lazy"><span class="venue-logo">{logo(v)}</span></span><div class="venue-caption"><div><small>{v['label']}</small><h3>{v['partner']}</h3></div>{arrow()}</div></a>''' for v in VENUES if v.get('image'))
    return f'''<section class="venue-section section shell" id="venues"><div class="section-head reveal"><div><p class="eyebrow">Our Bali address book</p><h2 class="section-title">Places we<br>work with.</h2></div><p>Across dining, music and hospitality.<br>A few more familiar names.</p></div><div class="venue-grid">{cards}</div><p class="source-note">Venue photography courtesy of Desa Kitsuné, Giselle and Bella. Explore each venue on its official website.</p></section>'''
def floating_gallery():
    order = ['patron','ella','jason','skool','wiz']
    cards = []
    for index, key in enumerate(order, 1):
        p = next(p for p in PROJECTS if p['id'] == key)
        caption = f"{p['short']} × {p['partner']}" if key not in ('jason','wiz') else p['title']
        cards.append(f'''<a class="floating-photo floating-photo-{index}" data-slide-index="{index-1}" data-tilt href="/marketing/#{p['id']}" data-project="{p['id']}" aria-label="Explore {html.escape(p['title'])}"><span class="floating-surface"><img draggable="false" src="/assets/projects/{p['image']}.jpg" alt="{html.escape(p['credit'])}" width="1080" height="1440" {'fetchpriority="high"' if index == 2 else 'decoding="async"'}><span class="floating-caption"><small>{'@luxeconciergebysl' if key == 'wiz' else '@social_luxe'}</small><strong>{caption}</strong>{arrow()}</span></span></a>''')
    dots = ''.join(f'<button class="gallery-dot" data-slide="{i}" aria-label="Show {html.escape(next(p["title"] for p in PROJECTS if p["id"] == key))}"' + (' aria-current="true"' if i == 0 else '') + '><span></span></button>' for i,key in enumerate(order))
    return f'''<div class="floating-gallery" data-hero-gallery><p class="sr-only" id="gallery-instructions">Featured collaborations. Use the arrow buttons or drag to explore. Movement pauses while using the keyboard.</p><div class="floating-deck" tabindex="0" role="region" aria-roledescription="carousel" aria-label="Five featured collaborations" aria-describedby="gallery-instructions"><div class="floating-track"><div class="floating-set" data-original>{''.join(cards)}</div></div></div><div class="hero-rail-controls gallery-controls-row shell"><span class="gallery-live-label"><span class="status-dot" aria-hidden="true"></span>The Social Luxe edit</span><div class="gallery-dots" role="group" aria-label="Choose a featured collaboration">{dots}</div><div class="gallery-navigation"><span class="hero-rail-status" aria-hidden="true">01 / 05</span><button class="hero-prev" aria-label="Previous collaboration">←</button><button class="hero-next" aria-label="Next collaboration">→</button></div></div><span class="sr-only gallery-announcement" aria-live="polite" aria-atomic="true"></span></div>'''

def modal():
    return '''<dialog id="project-dialog" aria-labelledby="project-title"><button class="dialog-close" aria-label="Close project">×</button><div class="dialog-layout"><div class="dialog-visual"><img id="dialog-photo" alt="" width="1080" height="1400"><div class="dialog-photo-controls"><button id="photo-prev" aria-label="Previous photo">←</button><span id="photo-count" aria-live="polite"></span><button id="photo-next" aria-label="Next photo">→</button></div></div><div class="dialog-copy"><p id="project-category" class="eyebrow"></p><h2 id="project-title"></h2><div id="dialog-logo"></div><p id="project-description"></p><dl><div><dt>Location</dt><dd id="project-place"></dd></div><div><dt>Published</dt><dd id="project-date"></dd></div></dl><a id="project-source" class="button" href="https://www.instagram.com/social_luxe/" target="_blank" rel="noopener noreferrer">View original post <span aria-hidden="true">↗</span></a><a id="project-photo-source" class="text-link" href="https://www.instagram.com/social_luxe/" target="_blank" rel="noopener noreferrer" hidden>View photo publication ↗</a><p id="project-credit" class="source-note"></p></div></div></dialog>'''
def faq(items):
    return '<div class="faq-list">'+''.join(f'<details><summary>{q}</summary><p>{a}</p></details>' for q,a in items)+'</div>'
HOME = f'''
<section class="visual-hero floating-hero"><div class="shell hero-heading"><p class="eyebrow hero-enter"><span class="status-dot"></span> Based in Bali. Working internationally.</p><h1 class="hero-enter">{wordmark()}</h1><div class="hero-subline hero-enter"><p>Influencer partnerships.<br>Private experiences.</p><div>{button('Explore our work','/marketing/#work')}<a class="text-link" href="/concierge/">Meet Luxe Concierge {arrow()}</a></div></div></div>
{floating_gallery()}<div class="shell hero-stage-footer"><a href="/marketing/#work" class="text-link">See all collaborations {arrow()}</a><button id="motion-toggle" class="motion-toggle" aria-pressed="false"><span aria-hidden="true">Ⅱ</span> Pause motion</button></div></section>
{brand_strip()}
<section class="worlds-section section"><div class="shell"><div class="section-head reveal"><div><p class="eyebrow">The Social Luxe house</p><h2 class="section-title">Two ways in.</h2></div><p>For your brand.<br>For your own plans.</p></div><div class="worlds-grid"><article class="world-card marketing-world reveal" data-shine><span class="eyebrow">01 / For brands &amp; venues</span><h3>Social Luxe<span>.</span></h3><p>Creator partnerships, brand collaborations<br>and hospitality experiences.</p><div class="stacked-images" aria-hidden="true"><img src="/assets/projects/ziara-patron.jpg" alt="" loading="lazy"><img src="/assets/projects/tyniesha-skool.jpg" alt="" loading="lazy"></div>{button('Explore marketing','/marketing/','button-light')}</article><article class="world-card concierge-world reveal delay-1" data-shine><img class="world-backdrop" src="/assets/projects/wiz-dinner.jpg" alt="The private dinner setting prepared for Wiz Khalifa in Bali" loading="lazy"><div class="world-content"><span class="eyebrow">02 / For private clients</span>{concierge_mark('h3')}<p>Private dining, stays and personal requests.<br>Tell us where you want to be.</p>{button('Explore the concierge','/concierge/')}</div></article></div></div></section>
<section class="section shell bali-section"><div class="bali-title reveal"><p class="eyebrow">Our point of view</p><h2 class="section-title">Bali is<br><span class="script">home.</span></h2><span class="coordinate">8.4095° S · 115.1889° E</span></div><div class="bali-copy reveal"><p class="body-large">We bring brands, venues and people together on the island. And we’re taking those connections further.</p><p>Founded by Grace Kelly, Social Luxe combines influencer partnerships with private hospitality. For a project in Bali or a brief beyond the island, start with a conversation.</p><a class="text-link" href="/the-house/">Inside Social Luxe ↗</a></div></section>{contact_band()}'''
MARKETING = f'''
<section class="shell page-intro page-intro-grid"><div><p class="eyebrow hero-enter">For brands &amp; establishments</p><h1 class="display hero-enter">Your brand.<br>The right<br><span class="script pink">people.</span></h1></div><div class="page-intro-copy hero-enter"><p class="body-large">Creator partnerships and brand experiences, with Bali at the centre.</p>{button('Discuss a campaign','/enquire/?service=marketing')}</div></section>
{work_section(full=True)}{brand_strip()}{venue_section()}
<section class="section shell"><div class="section-head reveal"><div><p class="eyebrow">From introduction to experience</p><h2 class="section-title">Made around<br>your brief.</h2></div></div><div class="offerings"><details open><summary><span>01</span>Creator &amp; talent partnerships</summary><p>Find the people who make sense for your brand, discuss the collaboration and coordinate the agreed arrangements.</p></details><details><summary><span>02</span>Brand experiences</summary><p>Bring people together around your brand. From the venue and guest arrangements to the agreed content and timing, we coordinate the details with you.</p></details><details><summary><span>03</span>Hospitality collaborations</summary><p>Connect your restaurant, hotel or destination with creators and talent through a collaboration suited to the place.</p></details></div></section>{contact_band()}'''
CONCIERGE = f'''
<section class="concierge-hero"><img class="concierge-backdrop" src="/assets/projects/wiz-dinner.jpg" alt="A private dinner setting in Bali, from the Luxe Concierge archive" fetchpriority="high"><div class="concierge-hero-inner shell"><p class="eyebrow hero-enter">Private hospitality · Bali &amp; beyond</p><div class="hero-enter">{concierge_mark('h1')}</div><p class="hero-enter">The table. The stay.<br>The plans around them.</p><div class="hero-enter">{button('Plan a private booking','/enquire/?service=concierge')}</div><a class="concierge-photo-credit" href="/marketing/#wiz" data-project="wiz">From the archive: a private dinner for Wiz Khalifa ↗</a></div></section>
<section class="section shell concierge-intro"><div class="reveal"><p class="eyebrow">Your time in Bali</p><h2 class="section-title">A personal<br>point of contact.</h2></div><div class="reveal"><p class="body-large">For private clients, visiting talent and anyone planning something personal.</p><p>You don’t need to be a public figure to work with Luxe Concierge. Share your dates, your destination and the details that matter to you.</p><a class="text-link" href="/enquire/?service=concierge">Tell us what you have in mind ↗</a></div></section><section class="shell concierge-services"><article><span class="number">01</span><h3>Stays.</h3><p>The destination, the dates and the kind of place you’re looking for.</p></article><article><span class="number">02</span><h3>Dining.</h3><p>A table for two, a private room or a dinner for your guests.</p></article><article><span class="number">03</span><h3>Occasions.</h3><p>Birthdays, celebrations and the arrangements around them.</p></article><article><span class="number">04</span><h3>Personal requests.</h3><p>Arrival plans, transfers and anything else you’d like to discuss.</p></article></section>
{work_section([p for p in PROJECTS if p['category']=='hosting'],'A few private moments.')}<section class="section shell page-faq"><div><p class="eyebrow">Before you enquire</p><h2 class="section-title">A few details.</h2></div>{faq([('Is this only for talent and public figures?','No. Luxe Concierge works with private clients as well as visiting talent. You do not need to be a creator or public figure to enquire.'),('Can you help outside Bali?','Tell us your destination and plans. We’ll discuss what can be arranged and confirm the scope before proceeding.'),('Does an enquiry confirm a reservation?','No. Availability, fees, pricing and booking terms must be agreed before any reservation is confirmed.')])}</section>{contact_band()}'''
HOUSE = f'''<section class="shell page-intro house-intro"><p class="eyebrow hero-enter">The house</p><h1 class="display hero-enter">Social Luxe.<br>Based in <span class="script pink">Bali.</span></h1><p class="body-large hero-enter">A marketing house and private concierge, founded by Grace Kelly.</p></section><section class="section shell founder-layout"><div class="founder-card reveal"><span class="founder-monogram" aria-hidden="true">SL.</span><span class="script">Grace Kelly</span><span class="eyebrow">Founder · Social Luxe</span></div><div class="founder-story reveal"><h2 class="section-title">People, places<br>and a personal<br>approach.</h2><p>For brands and establishments, Social Luxe brings together creators, talent and hospitality through collaborations.</p><p>For private clients, Luxe Concierge arranges reservations and personal experiences. The same attention to people and details runs through both.</p><p>Bali is our base. As Social Luxe grows internationally, every new project starts with a conversation.</p>{button('Get in touch','/enquire/')}</div></section>{contact_band()}'''

def write_page(path,title,description,content,active='',body_class=''):
    folder=PUBLIC/path;folder.mkdir(parents=True,exist_ok=True)
    data=json.dumps(PROJECTS,ensure_ascii=False).replace('<','\\u003c')
    markup=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title}</title><meta name="description" content="{description}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#f7f5f2"><meta property="og:title" content="{title}"><meta property="og:description" content="{description}"><meta property="og:type" content="website"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="/assets/fonts/inter-tight.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script>{'<script src="/motion-gallery.js" defer></script>' if path=='' else ''}<script src="/hover-effects.js" defer></script></head><body class="{body_class}">{header(active)}<main id="main">{content}</main>{footer()}{modal()}<script id="projects-data" type="application/json">{data}</script></body></html>'''
    (folder/'index.html').write_text(unify_arrows(markup))
write_page('','Social Luxe — Bali & Beyond','Influencer partnerships and private experiences. Social Luxe is based in Bali and working internationally.',HOME,body_class='home-page')
write_page('marketing','Marketing & Partnerships — Social Luxe','Creator partnerships, brand experiences and hospitality collaborations with Social Luxe in Bali.',MARKETING,'marketing')
write_page('concierge','Luxe Concierge by Social Luxe','Private hospitality, reservations and personal requests in Bali and beyond.',CONCIERGE,'concierge','concierge-page')
write_page('the-house','The House — Social Luxe','Meet Social Luxe, founded by Grace Kelly. Based in Bali, working internationally.',HOUSE,'house')
write_page('enquire','Make an Enquiry — Social Luxe','Discuss a brand collaboration or a private booking with Social Luxe.',(ROOT/'templates/enquire.html').read_text())
write_page('privacy','Privacy & Enquiries — Social Luxe','How information and enquiries are handled on this website.',(ROOT/'templates/privacy.html').read_text())
# A tiny fallback redirect also supports static previews and preserves project hashes.
(PUBLIC/'work').mkdir(exist_ok=True)
(PUBLIC/'work/index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Marketing — Social Luxe</title><script>location.replace('/marketing/' + location.search + location.hash);</script><noscript><meta http-equiv="refresh" content="0;url=/marketing/"></noscript></head><body><p>Our collaborations are now in <a href="/marketing/">Marketing</a>.</p></body></html>''')
(PUBLIC/'robots.txt').write_text('User-agent: *\nDisallow: /\n')
(PUBLIC/'404.html').write_text(unify_arrows(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not found — Social Luxe</title><meta name="robots" content="noindex"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body>{header()}<main class="shell section" id="main"><p class="eyebrow">404 / Page not found</p><h1 class="section-title" style="margin:30px 0">Let’s get you back<br>to Social Luxe.</h1>{button('Back to the homepage','/')}</main>{footer()}</body></html>'''))
print('Built 6 pages and 404 in public/')
